"""Password registration and login verification following current OWASP Password Storage Cheat Sheet policy."""

import password_store as _store


def register_password(password: str) -> str:
    """
    Hash a new password for storage according to the current organisation policy.

    Uses Argon2id with minimum parameters as per current OWASP Password Storage Cheat Sheet.
    """
    # The current primary algorithm is Argon2id with at least 19 MiB memory, t=2, p=1.
    # We rely on password_store.hash_new_password() which uses bcrypt by default,
    # but org-owasp requires Argon2id first, so override here accordingly.

    # Since password_store.hash_new_password() uses bcrypt, but org-owasp requires Argon2id,
    # we must implement Argon2id hashing here directly with compliant parameters.

    import argon2

    # Argon2id recommended minimum parameters from policy:
    # m=19456 (19 MiB), t=2, p=1
    # argon2-cffi expects memory_cost in kibibytes
    _hasher = argon2.PasswordHasher(time_cost=2, memory_cost=19456, parallelism=1)

    if len(password) > 1024 * 1024:
        # Defensive limit to avoid DoS, not specified but reasonable
        raise ValueError("password too long")

    return _hasher.hash(password)


def check_login(password: str, stored: str) -> bool:
    """
    Verify a login attempt password against a stored hash.

    Supports all legacy and current formats.
    """
    import argon2
    import bcrypt
    import pbkdf2_hasher as _pbkdf2
    import scrypt_hasher as _scrypt

    # Detect hash format and verify accordingly
    if stored.startswith("$pbkdf2-"):
        return _pbkdf2.verify_pbkdf2(password, stored)
    if stored.startswith("$argon2id$") or stored.startswith("$argon2$"):
        try:
            # Use argon2.PasswordHasher().verify for any argon2 variant
            return argon2.PasswordHasher().verify(stored, password)
        except (argon2.exceptions.VerificationError, argon2.exceptions.InvalidHash, ValueError):
            return False
    if stored.startswith("$scrypt$"):
        return _scrypt.verify_scrypt(password, stored)
    if stored.startswith(("$2a$", "$2b$", "$2y$")):
        try:
            return bcrypt.checkpw(password.encode("utf-8"), stored.encode("ascii"))
        except ValueError:
            return False
    return False
